/**
 * @param {number} n
 * @return {number}
 */
var numOfWays = function(n) {
    let res = 0;

    const dfs = (cell, grid) => {
        const row = Math.floor(cell / 3);
        const col = cell % 3;

        if (row >= n) {
            res++;
            return;
        }

        if ((row === 0 || grid[row - 1][col] !== 'R') && (col === 0 || grid[row][col - 1] !== 'R')) {
            grid[row][col] = 'R';
            dfs(cell + 1, grid);
        }

        if ((row === 0 || grid[row - 1][col] !== 'Y') && (col === 0 || grid[row][col - 1] !== 'Y')) {
            grid[row][col] = 'Y';
            dfs(cell + 1, grid);
        }

        if ((row === 0 || grid[row - 1][col] !== 'G') && (col === 0 || grid[row][col - 1] !== 'G')) {
            grid[row][col] = 'G';
            dfs(cell + 1, grid);
        }
    };

    dfs(0, Array.from({ length: n }, () => Array(3)));

    return res;
};

/**
 * @param {number} n
 * @return {number}
 */
var numOfWays = function(n) {
    const MOD = 10 ** 9 + 7;
    let A = 6;
    let B = 6;

    for (let i = 2; i <= n; i++) {
        const newA = (2 * A + 2 * B) % MOD;
        const newB = (2 * A + 3 * B) % MOD;
        A = newA;
        B = newB;
    }

    return (A + B) % MOD;
};
